    "meta.desc.index": `Mana — MTG Archive: app for Android and Windows to organise your Magic: The Gathering collection and decks. Full catalogue, camera scanning, decks and collection value.`,
    "i.eyebrow": `App for Android and Windows · Magic: The Gathering`,
    "i.tagline": `Your Magic collection and decks, organised and always at hand. Works offline once the catalogue is downloaded.`,
    "i.cta1": `See what it does`,
    "i.cta2": `Support the project`,
    "nav.download": `Download`,
    "i.dl.h2": `Download it free`,
