    "nav.video": `Video`,
    "i.vid.h2": `See it in action`,
    "i.vid.sub": `A quick tour of the main features: scanner, collection, decks and life counter.`,
    "i.dl.play": `https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png`,
